              </div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-200">
        <form onSubmit={handleSubmit} className="flex gap-4">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            disabled={sessionData.current_state !== 'WAITING_FOR_INFO' && sessionData.current_state !== 'FINISHED'}
            placeholder={
                sessionData.current_state === 'FINISHED' 
                ? "La sesión ha finalizado. Refresca para comenzar de nuevo." 
                : sessionData.current_state !== 'WAITING_FOR_INFO'
                ? "Los agentes están trabajando..."
                : "Describe tu empresa o problema..."
            }
            className="flex-1 p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-cyan-600 focus:border-transparent transition-all disabled:bg-gray-100 disabled:text-gray-400"
          />
          <button
            type="submit"
            disabled={!inputValue.trim() || (sessionData.current_state !== 'WAITING_FOR_INFO' && sessionData.current_state !== 'FINISHED')}
            className="bg-cyan-600 hover:bg-cyan-700 text-white font-semibold px-6 py-3 rounded-xl transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
          >
            Enviar
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatUI;

export type AgentRole = 'user' | 'pedro' | 'juan' | 'system';

export interface ChatMessage {
  role: AgentRole;
  content: string;
  timestamp: number;
}

export type WorkflowState = 
  | 'WAITING_FOR_INFO' 
  | 'START_RESEARCH' 
  | 'DECIDE_FLOW' 
  | 'START_REPORT' 
  | 'FINISHED';

// Tipo de la aplicación (Frontend)
export interface SessionData {
  id: string;
  user_id: string;
  chat_history: ChatMessage[];
  company_info: string | null;
  research_results: string[]; 
  report_final: string | null;
  current_state: WorkflowState;
  research_counter: number;
  created_at?: string;
}

export interface ActionResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// Supabase Helper Types
export type Json =
  | string
  | number
  | boolean
  | null
  | { [key: string]: Json | undefined }
  | Json[]

// Definición de la Base de Datos para Supabase
// Usamos 'type' en lugar de 'interface' para mejor compatibilidad con inferencia
export type Database = {
  public: {
    Tables: {
      sessions: {
        Row: {
          id: string
          user_id: string
          chat_history: Json // En DB es JSONB
          company_info: string | null
          research_results: Json // En DB es JSONB
          report_final: string | null
          current_state: string // En DB es text
          research_counter: number
          created_at?: string
        }
        Insert: {
          id?: string
          user_id: string
          chat_history?: Json
          company_info?: string | null
          research_results?: Json
          report_final?: string | null
          current_state?: string
          research_counter?: number
          created_at?: string
        }
        Update: {
          id?: string
          user_id?: string
          chat_history?: Json
          company_info?: string | null
          research_results?: Json
          report_final?: string | null
          current_state?: string
          research_counter?: number
          created_at?: string
        }
      }
    }
  }
}

