import { GoogleGenAI } from '@google/genai';
import { createServerSupabaseAdmin } from '@/lib/supabase/supabase-client';
import { ChatMessage, Database, SessionData, ActionResponse } from '@/lib/types';

// Initialize Gemini safely
const getAI = () => {
  const apiKey = process.env.API_KEY || process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error("API_KEY is missing. Check your environment variables.");
  return new GoogleGenAI({ apiKey });
};

// System Prompts
const PEDRO_SYSTEM_PROMPT = `
Eres Pedro, un Ingeniero de IA Senior y Analista de Datos en 'Consultores Empresariales IA'.
Tu tono es: Analítico, Técnico, Objetivo y Directo.
Tu tarea es analizar la información de la empresa proporcionada e identificar puntos clave, riesgos técnicos y oportunidades de automatización.
Sé conciso. Usa terminología técnica adecuada.
`;

const JUAN_SYSTEM_PROMPT = `
Eres Juan, un Project Manager y Estratega de Negocios en 'Consultores Empresariales IA'.
Tu tono es: Ejecutivo, Estratégico, Empático y No-técnico.
Tu tarea es tomar los hallazgos técnicos de Pedro y sintetizarlos en un plan de acción ejecutivo.
Habla en términos de valor de negocio, ROI y estrategia. Eres amable y profesional.
`;

/**
 * Creates a new session safely on the server using Admin privileges.
 * Catches errors to prevent generic "Server Component" crashes.
 */
export async function createSession(userId: string): Promise<ActionResponse<SessionData>> {
  try {
    // Check Env Var explicitly
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error("Missing SUPABASE_SERVICE_ROLE_KEY");
      return { 
        success: false, 
        error: "Server Configuration Error: SUPABASE_SERVICE_ROLE_KEY is missing." 
      };
    }

    const supabase = createServerSupabaseAdmin();

    // FIX: Cast query builder to 'any' to bypass strict TS inference errors on Insert
    const { data: newSession, error: dbError } = await (supabase
      .from('sessions') as any)
      .insert({
        user_id: userId,
        chat_history: [],
        current_state: 'WAITING_FOR_INFO',
        research_counter: 0,
        research_results: [],
      })
      .select()
      .single();

    if (dbError) {
      console.error("DB Error in createSession:", dbError);
      // Handle Foreign Key constraint specifically
      if (dbError.code === '23503') {
        return { 
          success: false, 
          error: "Auth Error: The database requires a registered user. Anonymous sign-ins are disabled and random IDs are not allowed." 
        };
      }
      return { success: false, error: `Database Error: ${dbError.message}` };
    }

    return { success: true, data: newSession as SessionData };

  } catch (error: any) {
    console.error("Unexpected Error in createSession:", error);
    return { success: false, error: error.message || "Unknown server error" };
  }
}

/**
 * Main Entry Point for User Interaction
 */
export async function runConsultancyFlow(sessionId: string, userMessage: string): Promise<ActionResponse<SessionData>> {
  try {
    const supabase = createServerSupabaseAdmin();
    let ai;
    try {
      ai = getAI();
    } catch (e: any) {
       return { success: false, error: e.message };
    }

    // 1. Fetch current session state
    const { data: rawSession, error } = await supabase
      .from('sessions')
      .select('*')
      .eq('id', sessionId)
      .single();

    if (error || !rawSession) {
      return { success: false, error: 'Session not found in database.' };
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const dbSession = rawSession as any;

    const session: SessionData = {
      id: dbSession.id,
      user_id: dbSession.user_id,
      chat_history: dbSession.chat_history as unknown as ChatMessage[],
      company_info: dbSession.company_info,
      research_results: (dbSession.research_results as unknown as string[]) || [],
      report_final: dbSession.report_final,
      current_state: dbSession.current_state as any,
      research_counter: dbSession.research_counter
    };

    // Helper to update DB state
    const updateState = async (updates: Database['public']['Tables']['sessions']['Update']) => {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { id, ...cleanUpdates } = updates as any; 
      const queryBuilder = supabase.from('sessions') as any;
      await queryBuilder.update(cleanUpdates).eq('id', sessionId);
    };

    const appendMessage = async (msg: ChatMessage, currentHistory: ChatMessage[]) => {
      const newHistory = [...currentHistory, msg];
      await updateState({ chat_history: newHistory as unknown as any });
      return newHistory;
    };

    let currentHistory = session.chat_history || [];
    let researchResults = session.research_results || [];
    let researchCounter = session.research_counter || 0;

    // --- Step 1: User Input Processing ---
    currentHistory = await appendMessage(
      { role: 'user', content: userMessage, timestamp: Date.now() },
      currentHistory
    );

    if (session.current_state === 'WAITING_FOR_INFO') {
      await updateState({ 
        company_info: userMessage, 
        current_state: 'START_RESEARCH' 
      });
    }

    // --- Step 2: Agent Logic ---
    try {
      // === AGENT: PEDRO ===
      const pedroResponse1 = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        config: { systemInstruction: PEDRO_SYSTEM_PROMPT },
        contents: `Analiza esta información de la empresa: "${session.company_info || userMessage}". Identifica 3 vectores de ataque o mejora técnica.`,
      });

      const pedroText1 = pedroResponse1.text || 'Sin respuesta técnica.';
      researchResults.push(pedroText1);

      currentHistory = await appendMessage(
        { role: 'pedro', content: pedroText1, timestamp: Date.now() },
        currentHistory
      );

      researchCounter++;

      await updateState({ 
        research_results: researchResults as unknown as any,
        research_counter: researchCounter,
        current_state: 'DECIDE_FLOW'
      });

      // === DECISION NODE ===
      if (researchCounter < 2) {
        const pedroResponse2 = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          config: { systemInstruction: PEDRO_SYSTEM_PROMPT },
          contents: `Basado en tu análisis anterior: "${pedroText1}", profundiza en la infraestructura de datos necesaria. Sé muy específico técnicamente.`,
        });

        const pedroText2 = pedroResponse2.text || 'Sin detalle técnico adicional.';
        researchResults.push(pedroText2);

        currentHistory = await appendMessage(
          { role: 'pedro', content: pedroText2, timestamp: Date.now() },
          currentHistory
        );

        researchCounter++;
        await updateState({ 
          research_results: researchResults as unknown as any,
          research_counter: researchCounter 
        });
      }

      // === AGENT: JUAN ===
      await updateState({ current_state: 'START_REPORT' });

      const juanResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        config: { systemInstruction: JUAN_SYSTEM_PROMPT },
        contents: `
          La información de la empresa es: "${session.company_info || userMessage}".
          Los hallazgos técnicos de Pedro fueron: ${JSON.stringify(researchResults)}.

          Genera un reporte final estratégico para el cliente. Resume los puntos técnicos en beneficios de negocio y propón los siguientes pasos.
        `,
      });

      const juanText = juanResponse.text || 'Error generando reporte final.';

      currentHistory = await appendMessage(
        { role: 'juan', content: juanText, timestamp: Date.now() },
        currentHistory
      );

      // === FINISH ===
      await updateState({ 
        report_final: juanText,
        current_state: 'FINISHED'
      });

    } catch (agentError: any) {
      console.error("Agent Logic Error:", agentError);
      await appendMessage(
        { role: 'system', content: `Error interno de IA: ${agentError.message}`, timestamp: Date.now() },
        currentHistory
      );
    }

    // Final fetch
    const { data: finalSession } = await supabase.from('sessions').select('*').eq('id', sessionId).single();

    return { success: true, data: finalSession as unknown as SessionData };

  } catch (err: any) {
    console.error("runConsultancyFlow Critical Error:", err);
    return { success: false, error: err.message };
  }
}

'use client';

import React, { useEffect, useState } from 'react';
import ChatUI from '@/components/ChatUI';
import { createBrowserSupabaseClient } from '@/lib/supabase/supabase-client';
import { SessionData } from '@/lib/types';
import { createSession } from '@/app/actions';

export default function Home() {
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const [supabase] = useState(() => createBrowserSupabaseClient());

  useEffect(() => {
    let mounted = true;

    const initSession = async () => {
      try {
        setLoading(true);
        setErrorMsg(null);

        let userId: string;

        // 1. Try Anonymous Auth
        const { data: authData, error: authError } = await supabase.auth.signInAnonymously();

        if (authError) {
          console.warn("Auth Anónimo no disponible. Fallback UUID.", authError.message);
          if (typeof crypto !== 'undefined' && crypto.randomUUID) {
            userId = crypto.randomUUID();
          } else {
             userId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                return v.toString(16);
            });
          }
        } else {
          userId = authData.user?.id || crypto.randomUUID();
        }

        // 2. Create Session (Server Action)
        const response = await createSession(userId);

        if (!mounted) return;

        if (!response.success || !response.data) {
          throw new Error(response.error || "Falló la creación de sesión sin mensaje específico.");
        }

        setSessionData(response.data);
        setSessionId(response.data.id);
      } catch (err: any) {
        console.error("Initialization Error:", err);
        if (mounted) {
          setErrorMsg(err.message || "Error desconocido al iniciar sesión.");
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };

    initSession();

    return () => {
      mounted = false;
    };
  }, [supabase]);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-600 mb-4"></div>
        <p className="text-gray-500 font-medium">Iniciando sistema...</p>
      </div>
    );
  }

  if (errorMsg || !sessionId || !sessionData) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full text-center border-l-4 border-red-500">
          <h3 className="text-xl font-bold text-gray-800 mb-2">Error de Inicialización</h3>
          <div className="bg-red-50 text-red-700 p-4 rounded-lg mb-6 text-left overflow-auto max-h-48 text-sm">
            <p className="font-bold mb-1">Detalle del error:</p>
            <p>{errorMsg}</p>
          </div>

          <div className="text-left bg-gray-100 p-4 rounded text-xs text-gray-500 mb-6">
             <p className="font-bold">Guía de Solución:</p>
             <ul className="list-disc pl-4 space-y-1 mt-1">
               <li>Si el error menciona <code>SUPABASE_SERVICE_ROLE_KEY</code>, agrégala en las variables de entorno de Vercel (Settings &gt; Environment Variables).</li>
               <li>Si el error menciona <code>Database Error</code>, verifica que la tabla <code>sessions</code> existe en Supabase.</li>
               <li>Si el error menciona <code>Auth Error</code>, habilita "Anonymous Sign-ins" en Supabase Auth Settings.</li>
             </ul>
          </div>

          <button 
            onClick={() => window.location.reload()}
            className="bg-cyan-600 text-white px-6 py-2 rounded-lg hover:bg-cyan-700 transition-colors w-full"
          >
            Reintentar
          </button>
        </div>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-gray-100 py-8 px-4 sm:px-6 lg:px-8">
      <ChatUI sessionId={sessionId} initialSession={sessionData} />
    </main>
  );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { createBrowserSupabaseClient } from '@/lib/supabase/supabase-client';
import { SessionData, ChatMessage } from '@/lib/types';
import { runConsultancyFlow } from '@/app/actions';

interface ChatUIProps {
  sessionId: string;
  initialSession: SessionData;
}

const ChatUI: React.FC<ChatUIProps> = ({ sessionId, initialSession }) => {
  const [sessionData, setSessionData] = useState<SessionData>(initialSession);
  const [inputValue, setInputValue] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const [supabase] = useState(() => createBrowserSupabaseClient());

  // Scroll to bottom on new messages
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [sessionData.chat_history]);

  useEffect(() => {
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'sessions',
          filter: `id=eq.${sessionId}`,
        },
        (payload) => {
          setSessionData(payload.new as SessionData);
          if (payload.new.current_state === 'FINISHED') {
            setIsSending(false);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [sessionId, supabase]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isSending) return;

    setIsSending(true);
    const msg = inputValue;
    setInputValue('');

    // Optimistic Update for User Message
    const userMsg: ChatMessage = { role: 'user', content: msg, timestamp: Date.now() };
    setSessionData(prev => ({
      ...prev,
      chat_history: [...prev.chat_history, userMsg]
    }));

    try {
      // Trigger Server Action
      const response = await runConsultancyFlow(sessionId, msg);

      if (response.success && response.data) {
        setSessionData(response.data);
        if (response.data.current_state === 'FINISHED') {
          setIsSending(false);
        }
      } else {
        console.error('Flow Error:', response.error);
        // Show error message in chat
        const errorMsg: ChatMessage = { 
          role: 'system', 
          content: `Error: ${response.error || "Error de comunicación."}`, 
          timestamp: Date.now() 
        };
        setSessionData(prev => ({
          ...prev,
          chat_history: [...prev.chat_history, errorMsg]
        }));
        setIsSending(false);
      }
    } catch (err) {
      console.error('Error triggering flow:', err);
      setIsSending(false);
    }
  };

  // Status Indicator helper
  const getStatusText = (state: string) => {
    switch (state) {
      case 'WAITING_FOR_INFO': return 'Esperando información...';
      case 'START_RESEARCH': return 'Pedro está investigando...';
      case 'DECIDE_FLOW': return 'Analizando profundidad...';
      case 'START_REPORT': return 'Juan está redactando el reporte...';
      case 'FINISHED': return 'Consultoría Finalizada.';
      default: return 'Procesando...';
    }
  };

  return (
    <div className="flex flex-col h-[85vh] max-w-4xl mx-auto bg-white shadow-2xl rounded-xl overflow-hidden border border-gray-200">

      {/* Header */}
      <div className="bg-gray-900 p-4 border-b border-gray-800 flex justify-between items-center">
        <div>
          <h2 className="text-white font-bold text-lg">Consultores Empresariales IA</h2>
          <p className="text-gray-400 text-xs uppercase tracking-wider">Sistema Multi-Agente</p>
        </div>
        <div className="flex items-center gap-2">
          <span className={`h-2.5 w-2.5 rounded-full ${sessionData.current_state === 'FINISHED' ? 'bg-green-500' : 'bg-cyan-500 animate-pulse'}`}></span>
          <span className="text-cyan-100 text-xs font-mono">
            {getStatusText(sessionData.current_state)}
          </span>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-gray-50 space-y-6">
        {sessionData.chat_history.length === 0 && (
          <div className="text-center text-gray-400 mt-20">
            <p className="text-lg">Bienvenido.</p>
            <p className="text-sm">Por favor, describe tu empresa o pega una URL para comenzar el análisis.</p>
          </div>
        )}

        {sessionData.chat_history.map((msg, idx) => {
          const isUser = msg.role === 'user';
          const isPedro = msg.role === 'pedro';
          const isJuan = msg.role === 'juan';
          const isSystem = msg.role === 'system';

          return (
            <div
              key={idx}
              className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[80%] p-5 rounded-xl text-sm leading-relaxed shadow-sm relative ${
                  isUser
                    ? 'bg-white border border-gray-200 text-gray-800'
                    : isPedro
                    ? 'bg-emerald-50 text-gray-800 border-l-4 border-emerald-500'
                    : isJuan
                    ? 'bg-sky-50 text-gray-800 border-l-4 border-sky-500'
                    : 'bg-red-50 text-red-600 border border-red-200'
                }`}
              >
                {!isUser && !isSystem && (
                  <div className="mb-2 flex items-center gap-2">
                    <span className={`text-xs font-bold uppercase px-2 py-0.5 rounded ${
                        isPedro ? 'bg-emerald-100 text-emerald-700' : 'bg-sky-100 text-sky-700'
                    }`}>
                      {isPedro ? 'Ing. Pedro (IA)' : 'Juan (PM)'}
                    </span>
                  </div>
                )}
                <div className="whitespace-pre-wrap markdown-body">
                  {msg.content}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-200">
        <form onSubmit={handleSubmit} className="flex gap-4">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            disabled={sessionData.current_state !== 'WAITING_FOR_INFO' && sessionData.current_state !== 'FINISHED'}
            placeholder={
                sessionData.current_state === 'FINISHED' 
                ? "La sesión ha finalizado. Refresca para comenzar de nuevo." 
                : sessionData.current_state !== 'WAITING_FOR_INFO'
                ? "Los agentes están trabajando..."
                : "Describe tu empresa o problema..."
            }
            className="flex-1 p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-cyan-600 focus:border-transparent transition-all disabled:bg-gray-100 disabled:text-gray-400"
          />
          <button
            type="submit"
            disabled={!inputValue.trim() || (sessionData.current_state !== 'WAITING_FOR_INFO' && sessionData.current_state !== 'FINISHED')}
            className="bg-cyan-600 hover:bg-cyan-700 text-white font-semibold px-6 py-3 rounded-xl transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
          >
            Enviar
          </button>
        </form>
      </div>
    </div>
  );
};

