      <button
        type="submit"
        disabled={disabled}
        className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2.5 rounded-lg transition-colors disabled:opacity-50"
      >
        Enviar Diagnóstico
      </button>
    </form>
  );
};

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { createBrowserSupabaseClient } from '@/lib/supabase/supabase-client';
import { SessionData, ChatMessage, A2UIResponse } from '@/lib/types';
import { runConsultancyFlow } from '@/app/actions';
import { marked } from 'marked';
import { BusinessForm } from './A2UI/BusinessForm';
import { ImpactChart } from './A2UI/ImpactChart';
import { ProposalCard } from './A2UI/ProposalCard';
import { StepProcess } from './A2UI/StepProcess';

interface ChatUIProps {
  sessionId: string;
  initialSession: SessionData;
}

const ChatUI: React.FC<ChatUIProps> = ({ sessionId, initialSession }) => {
  const [sessionData, setSessionData] = useState<SessionData>(initialSession);
  const [inputValue, setInputValue] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const supabase = createBrowserSupabaseClient();

  useEffect(() => {
    marked.setOptions({ breaks: true, gfm: true });
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [sessionData.chat_history]);

  useEffect(() => {
    if (!sessionId) return;

    const channel = supabase
      .channel(`session-${sessionId}`)
      .on('postgres_changes', { 
        event: 'UPDATE', 
        schema: 'public', 
        table: 'sessions', 
        filter: `id=eq.${sessionId}` 
      }, (payload) => {
          setSessionData(payload.new as SessionData);
          if (payload.new.current_state === 'FINISHED') setIsSending(false);
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [sessionId, supabase]);

  const sendMessage = async (msg: string) => {
    if (!msg.trim() || isSending) return;
    setIsSending(true);

    const userMsg: ChatMessage = { role: 'user', content: msg, timestamp: Date.now() };
    setSessionData(prev => ({ ...prev, chat_history: [...prev.chat_history, userMsg] }));

    try {
      const response = await runConsultancyFlow(sessionId, msg);
      if (response.success && response.data) {
        setSessionData(response.data);
      } else {
        const errorMsg: ChatMessage = { role: 'system', content: `**Error:** ${response.error || "Ocurrió un problema técnico."}`, timestamp: Date.now() };
        setSessionData(prev => ({ ...prev, chat_history: [...prev.chat_history, errorMsg] }));
      }
    } catch (err) {
      console.error('Error triggering flow:', err);
    } finally {
      setIsSending(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    sendMessage(inputValue);
    setInputValue('');
  };

  const handleFormSubmit = (data: Record<string, string>) => {
    const formattedData = Object.entries(data)
      .map(([k, v]) => `${k.toUpperCase()}: ${v}`)
      .join(' | ');
    sendMessage(`He completado el diagnóstico con los siguientes datos: ${formattedData}`);
  };

  const renderMessageContent = (content: string) => {
    let a2ui: A2UIResponse | null = null;
    try {
      if (content.trim().startsWith('{')) {
        a2ui = JSON.parse(content);
      }
    } catch (e) {
      // No es JSON, se trata como texto plano
    }

    const messageText = a2ui?.message || content;
    const html = marked.parse(messageText);

    return (
      <div className="w-full">
        <div className="markdown-body" dangerouslySetInnerHTML={{ __html: html as string }} />

        {/* Renderizado condicional seguro de componentes A2UI */}
        {a2ui?.componentName === 'BusinessForm' && a2ui.data && (
          <BusinessForm 
            title={a2ui.data.title} 
            fields={a2ui.data.fields} 
            onSubmit={handleFormSubmit} 
            disabled={isSending}
          />
        )}
        {a2ui?.componentName === 'ImpactChart' && a2ui.data && (
          <ImpactChart {...a2ui.data} />
        )}
        {a2ui?.componentName === 'ProposalCard' && a2ui.data && (
          <ProposalCard {...a2ui.data} />
        )}
        {a2ui?.componentName === 'StepProcess' && a2ui.data && (
          <StepProcess {...a2ui.data} />
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-[85vh] max-w-5xl mx-auto bg-white shadow-2xl rounded-2xl overflow-hidden border border-gray-200">
      <div className="bg-gray-950 p-4 border-b border-gray-800 flex justify-between items-center shrink-0">
        <div>
          <h2 className="text-white font-bold text-lg tracking-tight">Consultores Empresariales <span className="text-cyan-400">IA</span></h2>
          <p className="text-gray-500 text-[10px] uppercase font-black tracking-widest">A2UI PROTOCOL ACTIVE</p>
        </div>
        <div className="flex items-center gap-2 bg-gray-900 px-3 py-1.5 rounded-full border border-gray-800">
          <span className={`h-2 w-2 rounded-full ${sessionData.current_state === 'FINISHED' ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-cyan-500 animate-pulse shadow-[0_0_8px_rgba(6,182,212,0.6)]'}`}></span>
          <span className="text-cyan-100 text-[10px] font-mono font-bold uppercase">
            {sessionData.current_state.replace(/_/g, ' ')}
          </span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 bg-slate-50 space-y-8">
        {sessionData.chat_history.map((msg, idx) => {
          const isUser = msg.role === 'user';
          const isPedro = msg.role === 'pedro';
          const isJuan = msg.role === 'juan';

          return (
            <div key={idx} className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[90%] p-6 rounded-2xl shadow-sm border transition-all duration-300 ${
                  isUser ? 'bg-white border-slate-200 text-slate-700 ml-12' :
                  isPedro ? 'bg-emerald-50/50 border-emerald-100 mr-12' :
                  isJuan ? 'bg-sky-50/50 border-sky-100 mr-12' : 'bg-red-50 text-red-600 border-red-200'
                }`}>
                {!isUser && msg.role !== 'system' && (
                  <div className="mb-4 flex items-center gap-2">
                    <span className={`text-[9px] font-black uppercase px-2.5 py-1 rounded-md shadow-sm border ${
                        isPedro ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-sky-500 text-white border-sky-400'
                    }`}>
                      {isPedro ? '🤖 ING. PEDRO' : '💼 ESTRATEGA JUAN'}
                    </span>
                  </div>
                )}
                {renderMessageContent(msg.content)}
              </div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-slate-200 shrink-0">
        <form onSubmit={handleSubmit} className="flex gap-3">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            disabled={isSending || sessionData.current_state === 'FINISHED'}
            placeholder={isSending ? "Nuestra IA está analizando..." : "Describe tu empresa o consulta..."}
            className="flex-1 p-3.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-cyan-600 outline-none disabled:bg-slate-50 transition-all shadow-inner"
          />
          <button
            type="submit"
            disabled={!inputValue.trim() || isSending || sessionData.current_state === 'FINISHED'}
            className="bg-cyan-600 hover:bg-cyan-700 text-white font-bold px-8 py-3 rounded-xl transition-all shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSending ? (
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 bg-white rounded-full animate-bounce"></span>
                <span className="w-2 h-2 bg-white rounded-full animate-bounce [animation-delay:0.2s]"></span>
                <span className="w-2 h-2 bg-white rounded-full animate-bounce [animation-delay:0.4s]"></span>
              </div>
            ) : "Enviar"}
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatUI;

'use server';

import { GoogleGenAI } from "@google/genai";
import { createServerSupabaseAdmin } from '@/lib/supabase/supabase-client';
import { ChatMessage, Database, SessionData, ActionResponse, A2UIResponse } from '@/lib/types';

const getAI = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const PROTOCOL_INSTRUCTION = `
REGLA CRÍTICA DE SALIDA: Debes responder EXCLUSIVAMENTE en formato JSON.
Formato:
{
  "message": "[Texto persuasivo en Markdown]",
  "componentName": "[BusinessForm | ImpactChart | ProposalCard | StepProcess | null]",
  "data": { [Objeto con los datos específicos] }
}

Reglas por Componente:
- BusinessForm: "title" (string), "fields" (array de STRINGS). IMPORTANTE: Los elementos de "fields" deben ser nombres cortos de campos (ej: "nombre_empresa"). No olvides incluir "problema_a_resolver_con_ia".
- ImpactChart: "title" (string), "labels" (array strings), "values" (array números), "unit" (string).
- ProposalCard: "title" (string), "roi" (string), "cost" (string), "features" (array strings).
- StepProcess: "steps" (array strings), "currentStep" (número).
`;

const PEDRO_SYSTEM_PROMPT = `
Eres Pedro, Ingeniero IA Senior. Eres analítico y técnico.
Tu objetivo: Diagnosticar la viabilidad técnica y proponer automatizaciones.
${PROTOCOL_INSTRUCTION}
`;

const JUAN_SYSTEM_PROMPT = `
Eres Juan, Estratega de Negocios y PM. Eres ejecutivo y enfocado en ROI.
Tu objetivo: Transformar hallazgos técnicos en planes de negocio y roadmaps.
${PROTOCOL_INSTRUCTION}
`;

function cleanAndParseJSON(text: string): A2UIResponse {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      // Validación mínima de estructura
      if (parsed.message) return parsed;
    }
    return { message: text };
  } catch (e) {
    console.warn("Error parseando respuesta IA:", text);
    return { message: text };
  }
}

export async function createSession(userId: string): Promise<ActionResponse<SessionData>> {
  try {
    const supabase = createServerSupabaseAdmin();

    // Verificar si userId es un UUID válido para evitar error 422
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[4][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    const finalUserId = uuidRegex.test(userId) ? userId : '00000000-0000-4000-8000-000000000000';

    const { data: newSession, error: dbError } = await (supabase.from('sessions') as any)
      .insert({
        user_id: finalUserId,
        chat_history: [],
        current_state: 'WAITING_FOR_INFO',
        research_counter: 0,
        research_results: [],
      })
      .select()
      .single();

    if (dbError) {
      console.error("DB Error:", dbError);
      return { success: false, error: dbError.message };
    }
    return { success: true, data: newSession as SessionData };
  } catch (error: any) {
    return { success: false, error: error.message };
  }
}

export async function runConsultancyFlow(sessionId: string, userMessage: string): Promise<ActionResponse<SessionData>> {
  try {
    const supabase = createServerSupabaseAdmin();
    const ai = getAI();

    const { data: rawSession, error } = await supabase.from('sessions').select('*').eq('id', sessionId).single();
    if (error || !rawSession) return { success: false, error: 'Sesión no encontrada.' };

    const dbSession = rawSession as any;
    const session: SessionData = {
      id: dbSession.id,
      user_id: dbSession.user_id,
      chat_history: dbSession.chat_history as unknown as ChatMessage[],
      company_info: dbSession.company_info,
      research_results: (dbSession.research_results as unknown as string[]) || [],
      report_final: dbSession.report_final,
      current_state: dbSession.current_state as any,
      research_counter: dbSession.research_counter
    };

    const updateDB = async (updates: any) => {
      await (supabase.from('sessions') as any).update(updates).eq('id', sessionId);
    };

    let currentHistory = session.chat_history || [];
    let researchResults = session.research_results || [];

    // 1. Agregar mensaje de usuario
    currentHistory = [...currentHistory, { role: 'user', content: userMessage, timestamp: Date.now() }];
    await updateDB({ chat_history: currentHistory });

    // Lógica de agentes según el estado
    if (session.current_state === 'WAITING_FOR_INFO' && currentHistory.length === 1) {
      const pedroResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: PEDRO_SYSTEM_PROMPT },
        contents: `Preséntate brevemente y solicita los datos de la empresa. Usa el BusinessForm para preguntar: nombre, sector, tamaño y el problema específico que quieren resolver con IA.`,
      });
      const pedroData = cleanAndParseJSON(pedroResponse.text || '');
      currentHistory.push({ role: 'pedro', content: JSON.stringify(pedroData), timestamp: Date.now() });
      await updateDB({ chat_history: currentHistory });
    } 
    else {
      // Flujo de Análisis
      if (session.current_state === 'WAITING_FOR_INFO') {
        await updateDB({ company_info: userMessage, current_state: 'START_RESEARCH' });
      }

      const pedroAnalysis = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: PEDRO_SYSTEM_PROMPT },
        contents: `Analiza esta información: ${userMessage}. Genera un ImpactChart mostrando la mejora proyectada en eficiencia.`,
      });
      const pData = cleanAndParseJSON(pedroAnalysis.text || '');
      researchResults.push(pData.message);
      currentHistory.push({ role: 'pedro', content: JSON.stringify(pData), timestamp: Date.now() });

      const juanReport = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: JUAN_SYSTEM_PROMPT },
        contents: `Hallazgos técnicos: ${JSON.stringify(researchResults)}. Genera el plan estratégico final. Usa StepProcess para el roadmap y ProposalCard para la oferta final.`,
      });
      const jData = cleanAndParseJSON(juanReport.text || '');
      currentHistory.push({ role: 'juan', content: JSON.stringify(jData), timestamp: Date.now() });

      await updateDB({ 
        chat_history: currentHistory, 
        research_results: researchResults,
        current_state: 'FINISHED',
        report_final: jData.message 
      });
    }

    const { data: finalSession } = await supabase.from('sessions').select('*').eq('id', sessionId).single();
    return { success: true, data: finalSession as unknown as SessionData };

  } catch (err: any) {
    return { success: false, error: err.message };
  }
}

