  | 'BusinessForm' 
  | 'ImpactChart' 
  | 'ProposalCard' 
  | 'StepProcess'
  | 'ComparativeTable'
  | 'PriorityMatrix'
  | 'InteractiveROICalculator'
  | 'TechStackGrid'
  | 'SWOTAnalysis'
  | 'GanttMiniTimeline'
  | 'TestimonialCard'
  | 'RiskAssessment';

